"use strict";(globalThis.webpackChunkalpha_finance_docs=globalThis.webpackChunkalpha_finance_docs||[]).push([[938],{9577:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"alpha-finance-launch","metadata":{"permalink":"/alpha/blog/alpha-finance-launch","editUrl":"https://github.com/cuihairu/alpha/tree/main/docs/blog/blog/2024-01-01-alpha-finance-launch.md","source":"@site/blog/2024-01-01-alpha-finance-launch.md","title":"\ud83c\udf89 Alpha Finance \u6b63\u5f0f\u53d1\u5e03","description":"\u7ecf\u8fc7\u6570\u6708\u7684\u7cbe\u5fc3\u5f00\u53d1\uff0c\u6211\u4eec\u975e\u5e38\u9ad8\u5174\u5730\u5ba3\u5e03 Alpha Finance \u6b63\u5f0f\u53d1\u5e03\uff01\u8fd9\u662f\u4e00\u4e2a\u57fa\u4e8e Rust \u548c WebAssembly \u6784\u5efa\u7684\u9ad8\u6027\u80fd\u91d1\u878d\u6570\u636e\u5206\u6790\u5e73\u53f0\uff0c\u4e13\u4e3a\u4e13\u4e1a\u4ea4\u6613\u8005\u548c\u91d1\u878d\u673a\u6784\u8bbe\u8ba1\u3002","date":"2024-01-01T00:00:00.000Z","formattedDate":"2024\u5e741\u67081\u65e5","tags":[{"label":"announcement","permalink":"/alpha/blog/tags/announcement"},{"label":"release","permalink":"/alpha/blog/tags/release"},{"label":"rust","permalink":"/alpha/blog/tags/rust"},{"label":"webassembly","permalink":"/alpha/blog/tags/webassembly"}],"readingTime":5.86,"hasTruncateMarker":false,"authors":[{"name":"Alpha Finance Team","title":"\u5f00\u53d1\u56e2\u961f","url":"https://github.com/cuihairu/alpha","imageURL":"https://github.com/cuihairu.png","key":"alpha-team"}],"frontMatter":{"title":"\ud83c\udf89 Alpha Finance \u6b63\u5f0f\u53d1\u5e03","slug":"alpha-finance-launch","authors":["alpha-team"],"tags":["announcement","release","rust","webassembly"]},"unlisted":false},"content":"\u7ecf\u8fc7\u6570\u6708\u7684\u7cbe\u5fc3\u5f00\u53d1\uff0c\u6211\u4eec\u975e\u5e38\u9ad8\u5174\u5730\u5ba3\u5e03 **Alpha Finance** \u6b63\u5f0f\u53d1\u5e03\uff01\u8fd9\u662f\u4e00\u4e2a\u57fa\u4e8e Rust \u548c WebAssembly \u6784\u5efa\u7684\u9ad8\u6027\u80fd\u91d1\u878d\u6570\u636e\u5206\u6790\u5e73\u53f0\uff0c\u4e13\u4e3a\u4e13\u4e1a\u4ea4\u6613\u8005\u548c\u91d1\u878d\u673a\u6784\u8bbe\u8ba1\u3002\\n\\n## \ud83d\ude80 \u4e3a\u4ec0\u4e48\u9009\u62e9 Alpha Finance\uff1f\\n\\n### \u26a1 \u6781\u81f4\u6027\u80fd\\n\\nAlpha Finance \u5229\u7528 Rust \u7684\u96f6\u6210\u672c\u62bd\u8c61\u548c WebAssembly \u7684\u539f\u751f\u6027\u80fd\uff0c\u4e3a\u91d1\u878d\u6570\u636e\u5206\u6790\u63d0\u4f9b\u4e86\u524d\u6240\u672a\u6709\u7684\u5904\u7406\u80fd\u529b\uff1a\\n\\n- **\u6beb\u79d2\u7ea7\u6570\u636e\u67e5\u8be2**: \u4f7f\u7528 ClickHouse \u5217\u5f0f\u6570\u636e\u5e93\\n- **\u5b9e\u65f6\u6307\u6807\u8ba1\u7b97**: \u57fa\u4e8e Rust \u7684\u5185\u5b58\u5b89\u5168\u9ad8\u6027\u80fd\u8ba1\u7b97\\n- **\u4f4e\u5ef6\u8fdf\u6570\u636e\u5904\u7406**: \u4f18\u5316\u7684\u5f02\u6b65 I/O \u548c\u5e76\u53d1\u5904\u7406\\n\\n### \ud83d\udcca \u4e13\u4e1a\u7ea7\u529f\u80fd\\n\\n#### \u5e02\u573a\u6570\u636e\u5904\u7406\\n- \u652f\u6301 OHLCV \u6570\u636e\u7684\u9ad8\u6548\u5b58\u50a8\u548c\u67e5\u8be2\\n- \u591a\u65f6\u95f4\u5468\u671f\u6570\u636e\u5904\u7406\uff08\u4ece Tick \u5230\u6708\u7ea7\u522b\uff09\\n- \u538b\u7f29\u5b58\u50a8\u7b97\u6cd5\uff0c\u8282\u7701\u5b58\u50a8\u7a7a\u95f4 90%+\\n\\n#### \u6280\u672f\u6307\u6807\u5206\u6790\\n\u5185\u7f6e 60+ \u4e13\u4e1a\u6280\u672f\u6307\u6807\uff1a\\n\\n```rust\\n// \u793a\u4f8b\uff1a\u8ba1\u7b97\u79fb\u52a8\u5e73\u5747\u7ebf\\nuse alpha_core::indicators::MovingAverage;\\n\\nlet ma = MovingAverage::new(20, MovingAverageType::SMA);\\nlet result = ma.calculate(&price_data)?;\\n```\\n\\n#### \u5b9e\u65f6\u6570\u636e\u6d41\\n- WebSocket \u5b9e\u65f6\u6570\u636e\u63a8\u9001\\n- \u6beb\u79d2\u7ea7\u5ef6\u8fdf\u4fdd\u8bc1\\n- \u652f\u6301\u6570\u4e07\u5e76\u53d1\u8fde\u63a5\\n\\n### \ud83c\udfd7\ufe0f \u73b0\u4ee3\u5316\u67b6\u6784\\n\\nAlpha Finance \u91c7\u7528\u5fae\u670d\u52a1\u67b6\u6784\u8bbe\u8ba1\uff1a\\n\\n```\\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n\u2502   Web \u524d\u7aef      \u2502    \u2502   \u684c\u9762\u5e94\u7528      \u2502    \u2502   \u79fb\u52a8\u5e94\u7528      \u2502\\n\u2502   (React+WASM)   \u2502    \u2502    (Tauri)      \u2502    \u2502    (Flutter)    \u2502\\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n          \u2502                      \u2502                      \u2502\\n          \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n                                 \u2502\\n                    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n                    \u2502      API Gateway         \u2502\\n                    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n                                 \u2502\\n          \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n          \u2502                      \u2502                      \u2502\\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n\u2502  Real-time Feed  \u2502    \u2502   Data Engine   \u2502    \u2502    Collector    \u2502\\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n                                 \u2502\\n                    \u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\n                    \u2502      ClickHouse          \u2502\\n                    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\n```\\n\\n## \ud83d\udca1 \u6838\u5fc3\u6280\u672f\u7279\u6027\\n\\n### Rust + WebAssembly\\n\\n- **\u5185\u5b58\u5b89\u5168**: Rust \u7684\u6240\u6709\u6743\u7cfb\u7edf\u786e\u4fdd\u5185\u5b58\u5b89\u5168\\n- **\u9ad8\u6027\u80fd**: WebAssembly \u63d0\u4f9b\u63a5\u8fd1\u539f\u751f\u7684\u6027\u80fd\\n- **\u8de8\u5e73\u53f0**: \u4e00\u6b21\u7f16\u5199\uff0c\u5230\u5904\u8fd0\u884c\\n\\n### ClickHouse \u5217\u5f0f\u6570\u636e\u5e93\\n\\n- **\u67e5\u8be2\u901f\u5ea6**: \u6bd4\u4f20\u7edf\u6570\u636e\u5e93\u5feb 100 \u500d\u4ee5\u4e0a\\n- **\u538b\u7f29\u7387**: 10:1 \u7684\u6570\u636e\u538b\u7f29\u7387\\n- **\u53ef\u6269\u5c55\u6027**: \u652f\u6301 PB \u7ea7\u6570\u636e\u89c4\u6a21\\n\\n### \u5fae\u670d\u52a1\u67b6\u6784\\n\\n- **\u53ef\u7ef4\u62a4\u6027**: \u6a21\u5757\u5316\u8bbe\u8ba1\uff0c\u6613\u4e8e\u7ef4\u62a4\u548c\u6269\u5c55\\n- **\u9ad8\u53ef\u7528\u6027**: \u670d\u52a1\u9694\u79bb\uff0c\u6545\u969c\u4e0d\u5f71\u54cd\u6574\u4f53\u7cfb\u7edf\\n- **\u5f39\u6027\u4f38\u7f29**: \u6839\u636e\u8d1f\u8f7d\u81ea\u52a8\u6269\u5c55\u670d\u52a1\u5b9e\u4f8b\\n\\n## \ud83c\udf1f \u4f7f\u7528\u573a\u666f\\n\\n### \u4e2a\u4eba\u4ea4\u6613\u8005\\n- **\u4e13\u4e1a\u5206\u6790\u5de5\u5177**: \u544a\u522b Excel \u548c\u4f20\u7edf\u8f6f\u4ef6\u7684\u6027\u80fd\u9650\u5236\\n- **\u81ea\u5b9a\u4e49\u7b56\u7565**: \u652f\u6301\u81ea\u5b9a\u4e49\u6280\u672f\u6307\u6807\u548c\u4ea4\u6613\u7b56\u7565\\n- **\u6210\u672c\u6548\u76ca**: \u76f8\u6bd4\u5546\u4e1a\u8f6f\u4ef6\uff0c\u8282\u7701 90%+ \u6210\u672c\\n\\n### \u91cf\u5316\u56e2\u961f\\n- **\u9ad8\u6027\u80fd\u56de\u6d4b**: \u5feb\u901f\u9a8c\u8bc1\u4ea4\u6613\u7b56\u7565\\n- **\u5b9e\u76d8\u4ea4\u6613**: \u4f4e\u5ef6\u8fdf\u7684\u5b9e\u76d8\u4ea4\u6613\u7cfb\u7edf\\n- **\u6570\u636e\u79d1\u5b66**: \u5f3a\u5927\u7684\u6570\u636e\u5904\u7406\u548c\u5206\u6790\u80fd\u529b\\n\\n### \u91d1\u878d\u673a\u6784\\n- **\u5b9a\u5236\u5316\u5f00\u53d1**: \u6839\u636e\u9700\u6c42\u5b9a\u5236\u529f\u80fd\\n- **\u79c1\u6709\u90e8\u7f72**: \u652f\u6301\u672c\u5730\u548c\u4e91\u7aef\u90e8\u7f72\\n- **\u5408\u89c4\u6027**: \u7b26\u5408\u91d1\u878d\u884c\u4e1a\u6570\u636e\u5b89\u5168\u6807\u51c6\\n\\n## \ud83d\udcc8 \u6027\u80fd\u57fa\u51c6\\n\\n\u6211\u4eec\u5728\u6807\u51c6\u786c\u4ef6\u4e0a\u8fdb\u884c\u4e86\u6027\u80fd\u6d4b\u8bd5\uff1a\\n\\n| \u6307\u6807 | Alpha Finance | \u4f20\u7edf\u65b9\u6848 | \u63d0\u5347\u500d\u6570 |\\n|------|--------------|----------|----------|\\n| \u67e5\u8be2\u54cd\u5e94\u65f6\u95f4 | 2ms | 200ms | 100x |\\n| \u6307\u6807\u8ba1\u7b97\u901f\u5ea6 | 0.1ms | 5ms | 50x |\\n| \u6570\u636e\u538b\u7f29\u7387 | 90% | 30% | 3x |\\n| \u5e76\u53d1\u8fde\u63a5\u6570 | 10,000+ | 1,000 | 10x |\\n\\n## \ud83d\ude80 \u5feb\u901f\u5f00\u59cb\\n\\n### \u73af\u5883\u8981\u6c42\\n- **CPU**: 2\u6838\u5fc3\u4ee5\u4e0a\\n- **\u5185\u5b58**: 4GB \u4ee5\u4e0a\\n- **\u5b58\u50a8**: 20GB \u4ee5\u4e0a\\n\\n### \u4e00\u952e\u90e8\u7f72\\n```bash\\n# \u514b\u9686\u9879\u76ee\\ngit clone https://github.com/cuihairu/alpha.git\\ncd alpha\\n\\n# \u4e00\u952e\u90e8\u7f72\\nsudo ./scripts/deploy-ubuntu.sh\\n```\\n\\n### Docker \u90e8\u7f72\\n```bash\\n# \u4f7f\u7528 Docker Compose\\ndocker-compose up -d\\n\\n# \u8bbf\u95ee\u5e94\u7528\\nopen http://localhost:8080\\n```\\n\\n## \ud83d\udee3\ufe0f \u53d1\u5c55\u8def\u7ebf\u56fe\\n\\n### v1.1 (\u8ba1\u5212\u4e2d)\\n- [ ] \u66f4\u591a\u6280\u672f\u6307\u6807\\n- [ ] \u673a\u5668\u5b66\u4e60\u96c6\u6210\\n- [ ] \u4e91\u539f\u751f\u90e8\u7f72\u65b9\u6848\\n\\n### v1.2 (\u8ba1\u5212\u4e2d)\\n- [ ] \u79fb\u52a8\u7aef\u5e94\u7528\\n- [ ] \u7b56\u7565\u5e02\u573a\\n- [ ] \u793e\u533a\u529f\u80fd\\n\\n### v2.0 (\u957f\u671f\u89c4\u5212)\\n- [ ] \u591a\u8bed\u8a00\u652f\u6301\\n- [ ] \u4f01\u4e1a\u7ea7\u529f\u80fd\\n- [ ] \u56fd\u9645\u5316\u90e8\u7f72\\n\\n## \ud83e\udd1d \u52a0\u5165\u793e\u533a\\n\\nAlpha Finance \u662f\u4e00\u4e2a\u5f00\u6e90\u9879\u76ee\uff0c\u6211\u4eec\u6b22\u8fce\u6240\u6709\u5f62\u5f0f\u7684\u8d21\u732e\uff1a\\n\\n### \u8d21\u732e\u65b9\u5f0f\\n- **\u4ee3\u7801\u8d21\u732e**: \u63d0\u4ea4 PR \u4fee\u590d bug \u6216\u6dfb\u52a0\u65b0\u529f\u80fd\\n- **\u6587\u6863\u6539\u8fdb**: \u5b8c\u5584\u6587\u6863\u548c\u6559\u7a0b\\n- **\u95ee\u9898\u53cd\u9988**: \u62a5\u544a bug \u6216\u63d0\u51fa\u529f\u80fd\u5efa\u8bae\\n- **\u793e\u533a\u5efa\u8bbe**: \u5e2e\u52a9\u5176\u4ed6\u7528\u6237\u89e3\u51b3\u95ee\u9898\\n\\n### \u5f00\u53d1\u73af\u5883\\n```bash\\n# \u514b\u9686\u9879\u76ee\\ngit clone https://github.com/cuihairu/alpha.git\\n\\n# \u5b89\u88c5\u4f9d\u8d56\\nsudo apt install rustc cargo nodejs npm\\n\\n# \u5f00\u59cb\u5f00\u53d1\\ncargo run --bin alpha-api-gateway\\n```\\n\\n## \ud83d\udcc4 \u8bb8\u53ef\u8bc1\\n\\nAlpha Finance \u91c7\u7528 MIT \u8bb8\u53ef\u8bc1\uff0c\u5141\u8bb8\u5546\u4e1a\u548c\u5f00\u6e90\u4f7f\u7528\u3002\\n\\n## \ud83c\udf89 \u603b\u7ed3\\n\\nAlpha Finance \u7684\u53d1\u5e03\u6807\u5fd7\u7740\u91d1\u878d\u6570\u636e\u5206\u6790\u9886\u57df\u7684\u4e00\u4e2a\u91cd\u8981\u91cc\u7a0b\u7891\u3002\u6211\u4eec\u76f8\u4fe1\uff0c\u901a\u8fc7\u5c06 Rust \u7684\u6027\u80fd\u4f18\u52bf\u4e0e WebAssembly \u7684\u8de8\u5e73\u53f0\u7279\u6027\u7ed3\u5408\uff0c\u6211\u4eec\u4e3a\u91d1\u878d\u884c\u4e1a\u5e26\u6765\u4e86\u4e00\u6b21\u6280\u672f\u9769\u65b0\u3002\\n\\n**\u7acb\u5373\u5f00\u59cb\u60a8\u7684\u91d1\u878d\u6570\u636e\u5206\u6790\u4e4b\u65c5\uff1a**\\n- \ud83d\udcd6 [\u67e5\u770b\u6587\u6863](https://cuihairu.github.io/alpha/)\\n- \ud83d\udc19 [GitHub \u4ed3\u5e93](https://github.com/cuihairu/alpha)\\n- \ud83d\udcac [\u793e\u533a\u8ba8\u8bba](https://github.com/cuihairu/alpha/discussions)\\n\\n\u8ba9\u6211\u4eec\u4e00\u8d77\u6784\u5efa\u66f4\u7f8e\u597d\u7684\u91d1\u878d\u6570\u636e\u5206\u6790\u672a\u6765\uff01\\n\\n---\\n\\n*Alpha Finance \u56e2\u961f\\n2024\u5e741\u67081\u65e5*"}]}')}}]);